// Bet History — static data, no database. One record per graded game.
//
// Sign convention: `spread` and `prediction` are "home-team relation" —
// NEGATIVE = home favored/winning by that margin, POSITIVE = away
// favored/winning (the opposite of this site's usual away-perspective
// convention, where positive = home favored). This was empirically
// validated against all 1,504 real games, not assumed: comparing
// `prediction <= spread` reproduces the uploaded Every Bet Team column
// at 100% agreement (ties resolve to the home team), and
// `(awayScore - homeScore) - spread` reproduces the uploaded Actual
// Cover Team column at 100% agreement (ties also resolve home — this
// spreadsheet doesn't track true pushes as a separate case). See
// computeCustomGrading in lib/betHistory.ts for the exact formulas.
//
// Two tabs on the Admin page use this differently:
// - PLAIN HISTORY reads the precomputed columns below exactly as
//   uploaded — the actual historical record, unchanged.
// - CUSTOM ignores the precomputed columns entirely and recomputes
//   everything fresh from the raw inputs (homeScore, awayScore, spread,
//   prediction) using live-adjustable parameters.
//
// Loaded from the 2024-2025 upload. A handful of team names were
// normalized to match this site's canonical spelling (same team, just
// inconsistently spelled across rows in the source spreadsheet):
//   Appalachian State -> App State
//   Connecticut -> UConn
//   Louisiana Monroe -> UL Monroe
//   Southern Mississippi -> Southern Miss
//   Sam Houston State -> Sam Houston
//   UT San Antonio -> UTSA
// "postseason" (bowl/CFP games with no assigned week number) was mapped
// to week 17, one past the highest real regular-season week (16), so it
// sorts after the regular season and stays distinguishable. Worth a
// glance to confirm both choices read the way you want.

export type BetPick = "win" | "loss" | "push" | null;

export interface BetHistoryRecord {
  season: number;
  week: number;
  homeTeam: string;
  awayTeam: string;
  homeScore: number;
  awayScore: number;

  // --- Raw inputs — all the Custom tab needs ---
  spread: number; // Vegas closing line, home-team relation
  prediction: number; // model's projection, home-team relation

  // --- Precomputed, as uploaded — used as-is by Plain History ---
  actualFinalSpread: number; // homeScore - awayScore
  everyBetTeam: string | null;
  amountOff: number;
  absAmountOff: number;
  filteredBetTeam: string | null;
  weightedFilteredBetTeam: string | null;
  actualCoverTeam: string | null;
  everyBetResult: BetPick;
  filteredBetResult: BetPick;
  weightedFilteredBetResult: BetPick;
  absBettingLine: number;
  relativeAmountOff: number;
}

